"use strict";var JBT={rows:null,tab:"open",find:"",full:false};function jbtGroup(t){return t.panel||"the city"}function jbtFree(t){return t.positions-t.taken>0}function jbtRow(t){var e=t.positions-t.taken;return"<div style='display:flex;justify-content:space-between;align-items:center;gap:10px;padding:6px 0;border-bottom:1px solid var(--line)'>"+"<span>"+esc(t.title)+" <span style='color:var(--dim)'>· "+t.rate+" gold "+(t.pay_kind==="salary"?"a week":"an hour")+(t.workplace?" · "+esc(t.workplace):"")+(t.auto_hire===false?" · a keeper chooses":"")+"</span></span>"+"<span style='white-space:nowrap'>"+(e>0?"<button class='btn' data-apply='"+t.job_id+"'>"+(t.auto_hire===false?"Apply":"Take it")+"</button> <span style='color:var(--dim)'>"+e+" free</span>":"<span style='color:var(--dim)'>full</span>")+(typeof amKeeper==="function"&&amKeeper()?" <button class='btn' data-ktake='"+t.job_id+"' title='Keeper override: take it and clock in now'>Keeper: work it</button>":"")+"</span></div>"}function jbtPaint(){var t=document.getElementById("city-jobs");if(!t||!JBT.rows)return;var e=JBT.rows,n={},o=0;e.forEach(function(t){var e=jbtGroup(t);n[e]=n[e]||{all:0,free:0};n[e].all++;if(jbtFree(t)){n[e].free++;o++}});var a=Object.keys(n).sort();if(JBT.tab!=="open"&&!n[JBT.tab])JBT.tab="open";var r=function(t,e,n){var o=JBT.tab===t;return"<button type='button' class='btn' data-jbt='"+esc(t)+"' style='margin:0 6px 6px 0;padding:6px 10px;font-size:12.5px;border-radius:14px;"+(o?"background:var(--gold,#C9A040);color:#1E160A;border-color:var(--gold,#C9A040)":"")+"'>"+esc(e)+" <span style='opacity:.75'>"+n+"</span></button>"};var i="<input type='text' id='jbt-find' placeholder='find a job by name' value='"+esc(JBT.find)+"' style='margin:0 0 8px'>"+"<div style='display:flex;flex-wrap:wrap'>"+r("open","✨ Open now",o)+a.map(function(t){return r(t,t.charAt(0).toUpperCase()+t.slice(1),n[t].free)}).join("")+"</div>";var l=JBT.find.trim().toLowerCase(),p;if(l)p=e.filter(function(t){return[t.title,t.workplace,t.panel].join(" ").toLowerCase().indexOf(l)>=0});else if(JBT.tab==="open")p=e.filter(jbtFree);else p=e.filter(function(t){return jbtGroup(t)===JBT.tab});var s=0;if(!JBT.full&&JBT.tab!=="open"){var u=p.filter(jbtFree);s=p.length-u.length;p=u}p.sort(function(t,e){return jbtGroup(t)<jbtGroup(e)?-1:jbtGroup(t)>jbtGroup(e)?1:e.rate-t.rate});i+="<div id='jbt-list' style='max-height:420px;overflow-y:auto;-webkit-overflow-scrolling:touch'>";if(!p.length)i+="<p style='color:var(--dim)'>"+(l?"No job by that name.":"Nothing free here just now. Try another tab.")+"</p>";else{var c=null;p.forEach(function(t){if((JBT.tab==="open"||l)&&jbtGroup(t)!==c){c=jbtGroup(t);i+="<div style='margin-top:8px;color:var(--gold);font-size:12px;letter-spacing:.08em;text-transform:uppercase'>"+esc(c)+"</div>"}i+=jbtRow(t)})}i+="</div>";if(s||JBT.full&&JBT.tab!=="open")i+="<div style='margin-top:6px'><button type='button' class='btn' data-jbtfull='1' style='font-size:12px'>"+(JBT.full?"Hide full posts":"Show "+s+" full post"+(s===1?"":"s"))+"</button></div>";t.innerHTML=i;t.querySelectorAll("[data-jbt]").forEach(function(t){t.onclick=function(){JBT.tab=t.getAttribute("data-jbt");JBT.find="";jbtPaint();var e=document.getElementById("jbt-list");if(e)e.scrollTop=0}});var f=t.querySelector("[data-jbtfull]");if(f)f.onclick=function(){JBT.full=!JBT.full;jbtPaint()};var d=document.getElementById("jbt-find");if(d){d.addEventListener("keydown",function(t){t.stopPropagation()});d.oninput=function(){JBT.find=d.value;var t=d.selectionStart;jbtPaint();var e=document.getElementById("jbt-find");if(e){e.focus();try{e.setSelectionRange(t,t)}catch(t){}}}}t.querySelectorAll("[data-ktake]").forEach(function(t){t.onclick=function(){keeperTakeJob(+t.getAttribute("data-ktake"))}});t.querySelectorAll("[data-apply]").forEach(function(t){t.onclick=function(){var n=e.filter(function(e){return e.job_id===+t.getAttribute("data-apply")})[0];applyFor(+t.getAttribute("data-apply"),n&&n.auto_hire===false?prompt("A word about why you want it?")||null:null)}})}function showJobBoard(){var t=document.getElementById("city-jobs");if(!t)return;if(!JBT.rows)t.innerHTML="Looking…";jobBoard().then(function(e){if(!e||!e.length){JBT.rows=null;t.innerHTML="<span style='color:var(--dim)'>"+notOpenYet("No work is listed yet. The board isn't open.","No work listed. Run the latest server update and 8 in the SQL Editor.")+"</span>";return}JBT.rows=e;jbtPaint()})}
